SELECT Name, Sex, Age, Pclass
FROM titanic
LIMIT 5;

SELECT *
FROM titanic
LIMIT 3;

SELECT name
FROM sqlite_master
WHERE type = 'table';

SELECT COUNT(*) AS yolcu
FROM titanic
WHERE Sex = 'female' AND Pclass = 3;

SELECT
  (SELECT COUNT(*) FROM titanic WHERE Sex = 'female' AND (Pclass = 1 OR Pclass = 2)) AS parantezli,
  (SELECT COUNT(*) FROM titanic WHERE Sex = 'female' AND Pclass = 1 OR Pclass = 2) AS parantezsiz;

SELECT
  (SELECT COUNT(*) FROM titanic WHERE Age = NULL) AS esittir_null,
  (SELECT COUNT(*) FROM titanic WHERE Age IS NULL) AS is_null;

SELECT
  (SELECT ROUND(SUM(Freight), 2) FROM Orders) AS dogru_navlun,
  (SELECT ROUND(SUM(o.Freight), 2) FROM Orders o JOIN OrderDetails od ON od.OrderID = o.OrderID) AS sisirilmis_navlun;

SELECT ProductName
FROM Products
WHERE ProductID IN (
  SELECT ProductID FROM OrderDetails WHERE Quantity >= 120
)
ORDER BY ProductName;

SELECT CompanyName
FROM Customers c
WHERE NOT EXISTS (
  SELECT 1 FROM Orders o WHERE o.CustomerID = c.CustomerID
)
ORDER BY CompanyName;

SELECT Name
FROM titanic
WHERE ROW_NUMBER() OVER (ORDER BY Age DESC) = 1;

SELECT COUNT(*) AS siparis_1997
FROM Orders
WHERE OrderDate >= '1997-01-01' AND OrderDate < '1998-01-01';

WITH RECURSIVE sayi(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM sayi WHERE n < 5
)
SELECT n FROM sayi;

-- BigQuery
SELECT COUNTIF(Survived = 1) AS kurtulan FROM titanic;
-- PostgreSQL
SELECT COUNT(*) FILTER (WHERE Survived = 1) AS kurtulan FROM titanic;
-- Her yerde çalışan
SELECT SUM(CASE WHEN Survived = 1 THEN 1 ELSE 0 END) AS kurtulan FROM titanic;
